<?php
require_once dirname(dirname(__DIR__)).'/src/bootstrap.php';$user=Auth::requireRole('donor');$error=null;
if(request_method('POST')){Csrf::verify();$campaignId=(int)($_POST['campaign_id']??0);$action=$_POST['action']??'book';$c=db()->prepare("SELECT c.*,(SELECT COUNT(*) FROM campaign_registrations cr WHERE cr.campaign_id=c.id AND cr.status='booked') booked FROM donation_campaigns c WHERE c.id=? AND c.status='active' AND c.event_date>=CURDATE()");$c->execute([$campaignId]);$campaign=$c->fetch();if(!$campaign)$error='Campaign is not available.';elseif($action==='cancel'){db()->prepare("UPDATE campaign_registrations SET status='cancelled' WHERE campaign_id=? AND donor_id=?")->execute([$campaignId,(int)$user['id']]);audit('campaign_booking_cancelled','campaign',$campaignId);flash('success','Appointment cancelled.');redirect('donor/campaigns.php');}else{$time=trim($_POST['appointment_time']??'');if(!preg_match('/^\d{2}:\d{2}$/',$time))$error='Select an appointment time.';elseif((int)$campaign['booked']>=(int)$campaign['capacity'])$error='This campaign is currently full.';elseif($time<substr($campaign['start_time'],0,5)||$time>substr($campaign['end_time'],0,5))$error='Appointment time must be within the campaign time window.';else{db()->prepare("INSERT INTO campaign_registrations(campaign_id,donor_id,appointment_time,status,attendance_status) VALUES(?,?,?,'booked','pending') ON DUPLICATE KEY UPDATE appointment_time=VALUES(appointment_time),status='booked',attendance_status='pending'")->execute([$campaignId,(int)$user['id'],$time]);audit('campaign_booked','campaign',$campaignId,['time'=>$time]);flash('success','Campaign appointment booked.');redirect('donor/campaigns.php');}}}
$rows=db()->query("SELECT c.*,h.name hospital_name,(SELECT COUNT(*) FROM campaign_registrations cr WHERE cr.campaign_id=c.id AND cr.status='booked') booked FROM donation_campaigns c JOIN hospitals h ON h.id=c.hospital_id WHERE c.status='active' AND c.event_date>=CURDATE() ORDER BY c.event_date,c.start_time")->fetchAll();$my=db()->prepare("SELECT cr.*,c.title,c.event_date,c.location,h.name hospital_name FROM campaign_registrations cr JOIN donation_campaigns c ON c.id=cr.campaign_id JOIN hospitals h ON h.id=c.hospital_id WHERE cr.donor_id=? ORDER BY c.event_date DESC LIMIT 30");$my->execute([(int)$user['id']]);$mine=[];foreach($my->fetchAll() as $r)$mine[(int)$r['campaign_id']]=$r;$pageTitle='Donation Campaigns';require dirname(dirname(__DIR__)).'/src/templates/header.php';?>
<section class="dashboard"><div class="container"><div class="dash-head"><div><div class="eyebrow">Donor workspace</div><h1>Donation campaigns & appointments</h1></div></div><?=donor_nav()?><?php if($error):?><div class="error-list"><?=e($error)?></div><?php endif;?><div class="cards"><?php if(!$rows):?><div class="card"><p class="empty">No active campaigns are currently scheduled.</p></div><?php endif;?><?php foreach($rows as $c):$reg=$mine[(int)$c['id']]??null;?><div class="card"><div class="eyebrow"><?=e($c['district'])?></div><h3><?=e($c['title'])?></h3><p><strong><?=e($c['event_date'])?></strong> · <?=e(substr($c['start_time'],0,5))?>–<?=e(substr($c['end_time'],0,5))?><br><?=e($c['location'])?><br><span class="small">Hosted by <?=e($c['hospital_name'])?> · <?=e((string)$c['booked'])?> / <?=e((string)$c['capacity'])?> booked</span></p><?php if($reg&&$reg['status']==='booked'):?><div class="info-note">Your appointment: <strong><?=e(substr($reg['appointment_time'],0,5))?></strong></div><form method="post"><?=Csrf::field()?><input type="hidden" name="campaign_id" value="<?=e((string)$c['id'])?>"><button class="btn btn-outline btn-sm" name="action" value="cancel">Cancel appointment</button></form><?php else:?><form method="post"><?=Csrf::field()?><input type="hidden" name="campaign_id" value="<?=e((string)$c['id'])?>"><div class="field"><label>Appointment time</label><input type="time" name="appointment_time" min="<?=e(substr($c['start_time'],0,5))?>" max="<?=e(substr($c['end_time'],0,5))?>" required></div><button class="btn btn-sm" name="action" value="book">Book appointment</button></form><?php endif;?></div><?php endforeach;?></div></div></section>
<?php require dirname(dirname(__DIR__)).'/src/templates/footer.php';?>
